// An in-memory task store.
export function createStore() {
  const tasks = [];
  let nextId = 1;

  const normaliseTags = (tags) => {
    if (tags == null) return [];
    const seen = new Set();
    const result = [];
    for (const raw of tags) {
      const tag = String(raw).trim().toLowerCase();
      if (!tag || seen.has(tag)) continue;
      seen.add(tag);
      result.push(tag);
    }
    return result;
  };

  return {
    add(title, options = {}) {
      const task = {
        id: nextId++,
        title,
        done: false,
        tags: normaliseTags(options.tags),
      };
      tasks.push(task);
      return { ...task, tags: [...task.tags] };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task, tags: [...task.tags] };
    },
    list(options = {}) {
      const tag =
        options.tag == null ? null : String(options.tag).trim().toLowerCase();
      const selected =
        tag === null
          ? tasks
          : tasks.filter((task) => task.tags.includes(tag));
      return selected.map((task) => ({ ...task, tags: [...task.tags] }));
    },
  };
}
