import { formatTask } from './format.js';

// Splits positional arguments from --tag options.
function parseArgs(args, { allowTags }) {
  const positional = [];
  const tags = [];
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === '--tag') {
      if (!allowTags) throw new Error('Unknown option: ' + arg);
      const value = args[index + 1];
      if (value === undefined || value.startsWith('--')) {
        throw new Error('--tag needs a value');
      }
      tags.push(value);
      index += 1;
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  return { positional, tags };
}

// Runs one command and returns the lines to print.
export function run(store, argv) {
  const [command, ...rest] = argv;
  if (command === 'add') {
    const { positional, tags } = parseArgs(rest, { allowTags: true });
    return [formatTask(store.add(positional.join(' '), { tags }))];
  }
  if (command === 'done') {
    const { positional } = parseArgs(rest, { allowTags: false });
    return [formatTask(store.complete(Number(positional[0])))];
  }
  if (command === 'list') {
    const { tags } = parseArgs(rest, { allowTags: true });
    return store.list({ tag: tags[0] }).map(formatTask);
  }
  throw new Error('Unknown command: ' + command);
}
