import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';
import { formatTask } from '../src/format.js';
import { run } from '../src/cli.js';

test('add and complete', () => {
  const store = createStore();
  const task = store.add('Buy milk');
  assert.equal(store.complete(task.id).done, true);
});

test('tags are trimmed, lower-cased and de-duplicated', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: [' Home ', 'home', 'ERRAND'] });
  assert.deepEqual(task.tags, ['home', 'errand']);
  assert.deepEqual(store.list()[0].tags, ['home', 'errand']);
});

test('tasks always have a tags array', () => {
  const store = createStore();
  assert.deepEqual(store.add('No tags').tags, []);
});

test('list filters by tag case-insensitively', () => {
  const store = createStore();
  store.add('Buy milk', { tags: ['home'] });
  store.add('Ship parcel', { tags: ['work'] });
  assert.equal(store.list().length, 2);
  assert.deepEqual(
    store.list({ tag: 'HOME' }).map((task) => task.title),
    ['Buy milk'],
  );
});

test('formatTask appends tags', () => {
  assert.equal(
    formatTask({ id: 1, title: 'Buy milk', done: false, tags: ['home', 'errand'] }),
    '[ ] 1 Buy milk #home #errand',
  );
  assert.equal(formatTask({ id: 1, title: 'Buy milk', done: false, tags: [] }), '[ ] 1 Buy milk');
});

test('cli add with --tag and list --tag', () => {
  const store = createStore();
  assert.deepEqual(run(store, ['add', 'Buy', 'milk', '--tag', 'home', '--tag', 'errand']), [
    '[ ] 1 Buy milk #home #errand',
  ]);
  run(store, ['add', 'Ship', 'parcel', '--tag', 'work']);
  assert.deepEqual(run(store, ['list', '--tag', 'HOME']), ['[ ] 1 Buy milk #home #errand']);
  assert.deepEqual(run(store, ['list']), [
    '[ ] 1 Buy milk #home #errand',
    '[ ] 2 Ship parcel #work',
  ]);
});

test('cli rejects unknown options and valueless --tag', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'Buy milk', '--x']), {
    message: 'Unknown option: --x',
  });
  assert.throws(() => run(store, ['list', '--tag']), {
    message: '--tag needs a value',
  });
  assert.throws(() => run(store, ['add', 'Buy milk', '--tag']), {
    message: '--tag needs a value',
  });
});
